def _rewrite_refs(schema: Any, refs: dict[str, str]) -> Any:
    """Copy `schema`, replacing each `$ref` found in `refs` with its mapped value."""
    if isinstance(schema, list):
        return [_rewrite_refs(item, refs) for item in schema]
    if not isinstance(schema, dict):
        return schema
    return {
        key: (
            refs.get(value, value)
            if key == "$ref" and isinstance(value, str)
            else value
            if key in _SCHEMA_VALUE_KEYWORDS
            else _rewrite_refs(value, refs)
        )
        for key, value in schema.items()
    }


class _ShownArgsSchema:
    """Show a JSON Schema for tool arguments while accepting any object.

    The schema becomes a definition named after the tool, and its own definitions
    become sibling definitions, so references inside it keep resolving once it is
    embedded in a larger schema.
    """

    def __init__(self, tool_name: str, schema: dict[str, Any]) -> None:
        self.tool_name = tool_name
        self.schema = schema

    def __get_pydantic_core_schema__(
        self, source: Any, handler: GetCoreSchemaHandler
    ) -> core_schema.CoreSchema:
        defs = {**self.schema.get("definitions", {}), **self.schema.get("$defs", {})}
        main = {k: v for k, v in self.schema.items() if k not in {"definitions", "$defs"}}
        # A `.` makes pydantic name the definition after the part following it.
        refs = {name: f"{self.tool_name}.{name}" for name in defs}

        def show(body: dict[str, Any]) -> Callable[..., dict[str, Any]]:
            def json_schema(_: Any, json_handler: Callable[..., Any]) -> dict[str, Any]:
                def resolve(ref: str) -> str:
                    return json_handler(core_schema.definition_reference_schema(ref))["$ref"]

                mapping = {"#": resolve(self.tool_name)}
                for name, ref in refs.items():
                    mapping[f"#/$defs/{name}"] = mapping[f"#/definitions/{name}"] = resolve(ref)
                return _rewrite_refs(body, mapping)

            return json_schema

        args = core_schema.dict_schema(
            keys_schema=core_schema.str_schema(),
            values_schema=core_schema.any_schema(),
            ref=self.tool_name,
            metadata={"pydantic_js_functions": [show(main)]},
        )
        nested = [
            core_schema.any_schema(ref=refs[name], metadata={"pydantic_js_functions": [show(body)]})
            for name, body in defs.items()
        ]
        return core_schema.definitions_schema(args, nested)


