def _args_type(tool_name: str, tool: BaseTool | None) -> Any:
    """The type the arguments of an edited call to `tool` must match."""
    if tool is None:
        return dict[str, Any]
    args_schema = tool.tool_call_schema
    if isinstance(args_schema, type) and issubclass(args_schema, BaseModel):
        # Checked against the arguments the model sees, but the tool receives the
        # reviewer's arguments as given, exactly like the model's own.
        return Annotated[args_schema, WrapValidator(_keep_input)]
    shown = args_schema if isinstance(args_schema, dict) else args_schema.schema()
    return Annotated[dict[str, Any], _ShownArgsSchema(tool_name, shown)]


def _decision_schema(
    allowed_decisions: Sequence[DecisionType],
    tool_name: str,
    tool: BaseTool | None = None,
) -> Any:
    """The type of the decisions a reviewer may give for a call to `tool_name`.

    It is a union of one decision type per allowed decision, in order, told apart by
    `type`, or the decision type itself when only one is allowed. An `edit` must name
    `tool_name` and give arguments matching `tool`'s arguments, if it has a pydantic
    argument schema; otherwise any arguments object is accepted.

    Args:
        allowed_decisions: The decisions allowed for the call.
        tool_name: Name of the tool being called.
        tool: The tool being called, if known.

    Returns:
        A type accepted by pydantic's `TypeAdapter`.

    Raises:
        ValueError: If `allowed_decisions` is empty or names an unknown decision.
    """
    branches = []
    for decision in dict.fromkeys(allowed_decisions):
        if decision == "edit":
            edited_action = TypedDict(  # type: ignore[misc]
                "EditedAction",
                {"name": Literal[tool_name], "args": _args_type(tool_name, tool)},  # type: ignore[valid-type]
            )
            edited_action.__doc__ = Action.__doc__
            edit_decision = TypedDict(  # type: ignore[misc]
                "EditDecision",
                {"type": Literal["edit"], "edited_action": edited_action},
            )
            edit_decision.__doc__ = EditDecision.__doc__
            branches.append(edit_decision)
        elif decision in _DECISION_TYPES:
            branches.append(_DECISION_TYPES[decision])
        else:
            msg = f"Unknown decision type {decision!r} for tool '{tool_name}'."
            raise ValueError(msg)
    if not branches:
        msg = f"No decisions are allowed for tool '{tool_name}'."
        raise ValueError(msg)
    if len(branches) == 1:
        return branches[0]
    return Annotated[Union[tuple(branches)], Field(discriminator="type")]  # noqa: UP007


