from typing import Any

import pytest
from langgraph.checkpoint.base import BaseCheckpointSaver
from langgraph.checkpoint.serde.jsonplus import JsonPlusSerializer
from pydantic import BaseModel, TypeAdapter, ValidationError
from typing_extensions import TypedDict

from langgraph.errors import InvalidResumeError
from langgraph.graph import START, StateGraph
from langgraph.types import Command, Durability, Interrupt, interrupt

pytestmark = pytest.mark.anyio


class Answer(BaseModel):
    age: int


class State(TypedDict):
    answers: list[Any]


def _graph(checkpointer: BaseCheckpointSaver, calls: list[Any]) -> Any:
    def ask(state: State) -> dict[str, Any]:
        first = interrupt("first", response_schema=Answer)
        second = interrupt("second", response_schema={"type": "string"})
        calls.append((first, second))
        return {"answers": [first, second]}

    builder = StateGraph(State)
    builder.add_node("ask", ask)
    builder.add_edge(START, "ask")
    return builder.compile(checkpointer=checkpointer)


def _resume_writes(graph: Any, config: Any) -> list[Any]:
    saved = graph.checkpointer.get_tuple(config)
    return [w for w in saved.pending_writes if w[1] == "__resume__" and w[2]]


def test_interrupt_carries_response_schema() -> None:
    plain = Interrupt(value=1, id="x")
    assert plain.response_schema is None
    assert repr(plain) == "Interrupt(value=1, id='x')"

    schema = {"type": "integer"}
    with_schema = Interrupt(value=1, id="x", response_schema=schema)
    assert with_schema.response_schema is schema
