"""Tests for `HumanInTheLoopMiddleware` with `interrupt_mode="per_call"`."""

from __future__ import annotations

import asyncio
import typing
from typing import TYPE_CHECKING, Any

import pytest
from langchain_core.messages import HumanMessage, ToolCall, ToolMessage
from langchain_core.tools import StructuredTool, tool
from langgraph.checkpoint.memory import InMemorySaver
from langgraph.prebuilt.tool_node import ToolRuntime
from langgraph.runtime import Runtime
from langgraph.types import Command
from pydantic import BaseModel, TypeAdapter, ValidationError, field_validator

from langchain.agents.factory import create_agent
from langchain.agents.middleware import ToolErrorMiddleware, ToolRetryMiddleware
from langchain.agents.middleware.human_in_the_loop import (
    _EDIT_NOTICE,
    HumanInTheLoopMiddleware,
    InterruptMode,
    _decision_schema,
)
from tests.unit_tests.agents.model import FakeToolCallingModel

if TYPE_CHECKING:
    from langchain_core.runnables import RunnableConfig
    from langgraph.types import Interrupt

    from langchain.agents.middleware.human_in_the_loop import InterruptOnConfig


class _Inner(BaseModel):
    v: int


class _WriteArgs(BaseModel):
    path: str
    content: str
    inner: _Inner | None = None

    @field_validator("path")
    @classmethod
    def _relative(cls, path: str) -> str:
        if path.startswith("/"):
            msg = "path must be relative"
            raise ValueError(msg)
        return path


def _agent(
    calls: list[dict[str, Any]],
    tool_calls: list[ToolCall],
    interrupt_on: dict[str, bool | InterruptOnConfig],
    extra: tuple[Any, ...] = (),
) -> Any:
    @tool(args_schema=_WriteArgs)
    def write(
        path: str, content: str, runtime: ToolRuntime, inner: _Inner | None = None
    ) -> str:
        """Write a file."""
        calls.append(
            {"path": path, "content": content, "inner": inner, "id": runtime.tool_call_id}
        )
        return f"wrote {path}"

    @tool
    def read(path: str) -> str:
        """Read a file."""
        calls.append({"read": path})
        return "data"

    return create_agent(
        model=FakeToolCallingModel(tool_calls=[tool_calls, []]),
        tools=[write, read],
        middleware=[
            HumanInTheLoopMiddleware(interrupt_on, interrupt_mode="per_call"),
            *extra,
        ],
        checkpointer=InMemorySaver(),
    )


def _by_call(interrupts: list[Interrupt]) -> dict[str, Interrupt]:
    return {i.value["tool_call_id"]: i for i in interrupts}


def _tool_messages(result: dict[str, Any]) -> dict[str, ToolMessage]:
    return {m.tool_call_id: m for m in result["messages"] if isinstance(m, ToolMessage)}


_CONFIG: RunnableConfig = {"configurable": {"thread_id": "1"}}
_WRITE = {"write": {"allowed_decisions": ["approve", "edit", "reject"]}}


def test_interrupt_mode_validation() -> None:
    assert typing.get_args(InterruptMode) == ("batched", "per_call")
    assert HumanInTheLoopMiddleware({}).interrupt_mode == "batched"
    with pytest.raises(ValueError, match=r"^`interrupt_mode` must be 'batched' or 'per_call', got 'sometimes'\.$"):
        HumanInTheLoopMiddleware({}, interrupt_mode="sometimes")  # type: ignore[arg-type]


def test_each_listed_call_pauses_on_its_own() -> None:
    calls: list[dict[str, Any]] = []
    agent = _agent(
        calls,
        [
            ToolCall(name="write", args={"path": "a", "content": "x"}, id="1"),
            ToolCall(name="write", args={"path": "b", "content": "y"}, id="2"),
            ToolCall(name="read", args={"path": "c"}, id="3"),
        ],
        {"write": {"allowed_decisions": ["approve", "reject"], "description": "Check it"}},
    )
    result = agent.invoke({"messages": [HumanMessage("go")]}, _CONFIG)

    pending = _by_call(result["__interrupt__"])
    assert pending["1"].value == {
        "type": "tool_approval",
        "tool_call_id": "1",
        "name": "write",
        "args": {"path": "a", "content": "x"},
        "description": "Check it",
    }
    assert set(pending) == {"1", "2"}
    assert calls == [{"read": "c"}]

    result = agent.invoke(Command(resume={pending["1"].id: {"type": "approve"}}), _CONFIG)
    assert [i.value["tool_call_id"] for i in result["__interrupt__"]] == ["2"]
    result = agent.invoke(
        Command(resume={pending["2"].id: {"type": "reject", "message": "no"}}), _CONFIG
    )
    assert "__interrupt__" not in result
    assert calls == [{"read": "c"}, {"path": "a", "content": "x", "inner": None, "id": "1"}]
    messages = _tool_messages(result)
    assert messages["2"].status == "error"
    assert messages["2"].content == "User rejected the tool call for `write` with reason: no"


def test_when_and_description_factory() -> None:
    calls: list[dict[str, Any]] = []
    runtimes: list[Any] = []

    def describe(tool_call: ToolCall, state: Any, runtime: Runtime[Any]) -> str:
        runtimes.append(runtime)
        return f"about {tool_call['args']['path']}"

    agent = _agent(
        calls,
        [
            ToolCall(name="write", args={"path": "a", "content": "x"}, id=""),
            ToolCall(name="write", args={"path": "skip", "content": "y"}, id="2"),
        ],
        {
            "write": {
                "allowed_decisions": ["approve"],
                "description": describe,
                "when": lambda req: req.tool_call["args"]["path"] != "skip",
            }
        },
    )
    result = agent.invoke({"messages": [HumanMessage("go")]}, _CONFIG)
    [pending] = result["__interrupt__"]
    assert pending.value["tool_call_id"] == ""
    assert pending.value["description"] == "about a"
    assert all(isinstance(r, Runtime) for r in runtimes)
    assert [c["path"] for c in calls] == ["skip"]

    agent.invoke(Command(resume={pending.id: {"type": "approve"}}), _CONFIG)
    assert [c["path"] for c in calls] == ["skip", "a"]


