    assert calls == []


@pytest.mark.parametrize("retry_first", [True, False])
@pytest.mark.parametrize("is_async", [False, True])
def test_retried_call_is_reviewed_once(retry_first: bool, is_async: bool) -> None:  # noqa: FBT001
    attempts: list[int] = []

    @tool
    def flaky(x: int) -> str:
        """Fail twice, then succeed."""
        attempts.append(x)
        if len(attempts) < 3:
            msg = "boom"
            raise RuntimeError(msg)
        return f"ok {x}"

    review = HumanInTheLoopMiddleware({"flaky": True}, interrupt_mode="per_call")
    retry = ToolRetryMiddleware(max_retries=3, initial_delay=0, jitter=False)
    agent = create_agent(
        model=FakeToolCallingModel(tool_calls=[[ToolCall(name="flaky", args={"x": 1}, id="1")], []]),
        tools=[flaky],
        middleware=[retry, review] if retry_first else [review, retry],
        checkpointer=InMemorySaver(),
    )

    def invoke(value: Any) -> dict[str, Any]:
        if is_async:
            return asyncio.run(agent.ainvoke(value, _CONFIG))
        return agent.invoke(value, _CONFIG)

    [pending] = invoke({"messages": [HumanMessage("go")]})["__interrupt__"]
    edit = {"type": "edit", "edited_action": {"name": "flaky", "args": {"x": 7}}}
    result = invoke(Command(resume={pending.id: edit}))
    assert "__interrupt__" not in result
    assert attempts == [7, 7, 7]
    assert str(_tool_messages(result)["1"].content).endswith("ok 7")


